-- eSpark Drive — folder tree, from the Electrical Scope Register Rev2.
-- Generated by scripts/generate-espark-seed.mjs. Load after schema.sql:
--   npx wrangler d1 execute <ESPARK_DB> --remote --file=./seed.espark.sql
